impl<A: Attribute> WeaponEffect<A> for ExaiphanesBladeEffect {
    fn apply(&self, data: &WeaponCommonData, attribute: &mut A) {
        // 该武器被动仅对「旅行者」（空/荧，含全部元素形态）生效。
        // 通过 CharacterSelector 依据 CharacterStatus 中的 CharacterName 进行限制，
        // 仅当装备者为旅行者时才选择自身（非旅行者装备时上述效果不生效）。
        let traveler_selector = CharacterSelector::new({
            let character_id = attribute.get_character().character_id;
            move |status: &CharacterStatus| {
                status.character_id == character_id
                    && status.character_static_data.name.is_traveler()
            }
        });

        // 旅行者命中敌人后，攻击力提升，持续8秒（战斗中旅行者持续命中敌人，视为常驻）。
        // 该数值随精炼等级非线性变化，按精炼等级匹配。
        let atk_bonus = match data.refine {
            1 => 0.16,
            2 => 0.20,
            3 => 0.24,
            4 => 0.32,
            5 => 0.40,
            _ => 0.0,
        };
        if atk_bonus > 0.0 {
            attribute.add_atk_percentage_s(traveler_selector.clone(), "星锋剑被动", atk_bonus);
        }

        // 精炼2阶及以上：每与一种元素共鸣过，旅行者的暴击伤害就会提升6%。
        // 共鸣元素数量由用户配置（0~7，默认7）。
        if data.refine >= 2 && self.resonated_elements > 0 {
            attribute.set_value_by_s(
                traveler_selector,
                AttributeType::Panel(AttributeName::CriticalDamageBase),
                "星锋剑被动",
                0.06 * self.resonated_elements as f64,
            );
        }

        // 恢复元素能量的效果不参与伤害计算，故不实现。
    }
}

